CREATE OR ALTER FUNCTION [dbo].[GenerateAssetUrl] ( @AssetID bigint ) RETURNS varchar(500) AS BEGIN declare @Url varchar(500) = ''; declare @Type varchar(50), @TypeID int, @ObjectID int = 0, @uid uniqueidentifier;
select @ObjectID = A.ObjectID, @Type = A.[Object], @TypeID = T.ObjectID, @uid = A.uid from Asset A inner join AssetType T on T.ID = A.AssetTypeID where A.ID = @AssetID;
SET @Url = CASE @Type WHEN 'Artifact' THEN 'artifact/' + + CAST(@TypeID as varchar) + '/' + CAST(@ObjectID as varchar) WHEN 'ReferenceItem' THEN 'reference/' + + CAST(@TypeID as varchar) WHEN 'FusionAttribute' THEN 'fusion/fusionattribute/' + CAST(@TypeID as varchar) + '/' + CAST(@ObjectID as varchar) WHEN 'Fusion' THEN 'fusion/' + CAST(@TypeID as varchar) + '/' + + CAST(@ObjectID as varchar) WHEN 'Group' THEN 'group/' + CAST(@ObjectID as varchar) WHEN 'Policy' THEN 'policy/' + CAST(@TypeID as varchar(15)) + '/id/' + CAST(@ObjectID as varchar) WHEN 'Resource' THEN 'resource/' + CAST(@ObjectID as varchar) WHEN 'Rule' THEN 'quality/rule/' + CAST(@TypeID as varchar) + '/' + CAST(@ObjectID as varchar) WHEN 'Taxonomy' THEN 'model/' + CAST(@TypeID as varchar) + '/id/' + CAST(@ObjectID as varchar) WHEN 'Task' THEN (SELECT '/sidebar/visualization/browser/'+lower(cast(a.uid as nvarchar(36)))+'/Process/' + lower(cast(@uid as nvarchar(36))) FROM AssetProcessDiagram APD CROSS APPLY (SELECT * FROM OPENJSON(APD.Diagram,'$.nodeDataArray') WITH ( uid uniqueidentifier '$.key' )) D INNER JOIN asset a on a.id = apd.AssetID WHERE D.uid = @uid) END
RETURN @Url END
